// GENUINE Postfix delivery status notifications, captured by the `@rapidmx/postfix-bridge` agent from a boky/postfix container in a
// docker lab on 2026-09-20 and copied verbatim from `postfix-bridge/test/fixtures/` (`dsn-*.eml`, `dsn-envelope.json`). The recipient
// domains are `.lab` placeholders (`owned.lab` is the local one, `refuse.lab`/`defer.lab` the remote ones); the DKIM signature in the
// returned message is the lab's own. Each is exactly what the bridge POSTs to `/internal/mta/deliver`: CRLF line endings, no
// `Return-Path`/`Authentication-Results` (the bridge adds none), and - see `DSN_ENVELOPE` - a NULL envelope sender that reaches the
// route as a present-but-EMPTY `X-Envelope-From` header.
//
// Stored as lines rather than as .eml files so line endings survive git's autocrlf on any platform; `toBuffer()` restores CRLF.
// The hand-written `postfixDsn()` in `postfixDsn.ts` remains for what no capture has: an HTML notification.

/** The SMTP transaction Postfix opened to hand the bounce over (`dsn-envelope.json`). */
export const DSN_ENVELOPE = {
    smtp: { mailFrom: "<>", mailFromParameters: "BODY=8BITMIME", rcptTo: ["alice@owned.lab"] },
    forwardedToIngest: { endpoint: "POST /internal/mta/deliver", contentType: "message/rfc822", "X-Envelope-From": "", "X-Envelope-To": "alice@owned.lab" },
} as const;

function toBuffer(lines: readonly string[]): Buffer {
    return Buffer.from(lines.join("\r\n") + "\r\n");
}

